\label{thm:iso}
Let $p>1$, $1\leq q<p^*$, and let $\Omega\subset\mathbb{R}^n$ be a bounded open set. Then
\begin{equation}\label{eq:iso}
\Lambda^{\mathcal{A}}_{p,q}(\Omega)\geq\Lambda_{p,q}(\Omega^\star),
\end{equation}
with equality if and only if $\Omega$ is an ellipsoid, up to a set of zero \emph{Sobolev} $p$-capacity.

\label{thm:KJ}
Let $p>1$, $1<q<p^*$, and let $\Omega\subset\mathbb{R}^n$ be a bounded open set. Then
\begin{equation}\label{eq:KJ}
T^{\mathcal{A}}_p(\Omega)^{(p-1)\sigma}\,\Lambda^{\mathcal{A}}_{p,q}(\Omega)\geq T_p(B^n)^{(p-1)\sigma}\,\Lambda_{p,q}(B^n),
\end{equation}
with $\sigma$ as in \eqref{eq:KJEuclid}. Equality holds if and only if $\Omega$ is an ellipsoid, up to a set of zero Sobolev $p$-capacity.

\label{thm:BPstab}
Let $p\geq1$. There exists $\gamma=\gamma(n,p)>0$ such that
\[
\frac{|\Gamma_pL|}{|L|}\geq1+\gamma\,\delta_{\mathrm{BM}}(L,B^n)^{840(n+p)}
\]
for every origin-symmetric convex body $L\subset\mathbb{R}^n$.

\label{lem:frozen}
Let $f\in W^{1,p}_0(\Omega)\setminus\{0\}$ for a bounded open set $\Omega\subset\mathbb{R}^n$, or $f\in D^{1,p}(\mathbb{R}^n)\setminus\{0\}$ with $1<p<n$. For every star body $L$ with $|L|=\omega_n$,
\begin{equation}\label{eq:frozen}
\mathcal{E}_p(f)^p\leq\int_{\mathbb{R}^n}h\big(\Gamma_pL,\nabla f(x)\big)^p\,dx,
\end{equation}
with equality if and only if $L=L_f$. Moreover, $h(\Gamma_pL_f,\cdot)=H_f$, the norm in \eqref{eq:affineLaplacian}.

\label{thm:Boroczky}
Let $p\geq1$. There exists $\gamma_0=\gamma_0(n,p)>0$ such that
\[
|M|^{\frac{n-p}{p}}\,|\Pi^*_pM|\leq\Big(1-\gamma_0\,\delta_{\mathrm{BM}}(M,B^n)^{840(n+p)}\Big)\,\omega_n^{\frac np}
\]
for every origin-symmetric convex body $M\subset\mathbb{R}^n$.

By \eqref{eq:GammaPi} and polar coordinates, $h(\Gamma_pL,v)^p=\frac{1}{n a_{n,p}|L|}\int_{S^{n-1}}\rho_L(\xi)^{n+p}|\langle v,\xi\rangle|^p\,d\xi$. By Fubini's theorem and \eqref{eq:GammaPi} again,
\begin{align*}
V_p(M,\Gamma_pL)&=\frac{1}{n^2a_{n,p}|L|}\int_{S^{n-1}}\rho_L(\xi)^{n+p}\Big(\int_{S^{n-1}}|\langle v,\xi\rangle|^p\,h_M(v)^{1-p}\,dS_M(v)\Big)\,d\xi\\
&=\frac{\omega_n}{n|L|}\int_{S^{n-1}}\rho_L(\xi)^{n+p}\,h(\Pi_pM,\xi)^p\,d\xi,
\end{align*}
and $h(\Pi_pM,\xi)=\rho_{\Pi^*_pM}(\xi)^{-1}$.

\label{prop:reduction}
Let $p>1$, $1<q<p^*$, let $\Omega\subset\mathbb{R}^n$ be a bounded open set and let $u$ be a minimizer for $\Lambda^{\mathcal{A}}_{p,q}(\Omega)$. Define $\varepsilon\geq0$ by $T^{\mathcal{A}}_p(\Omega)^{(p-1)\sigma}\Lambda^{\mathcal{A}}_{p,q}(\Omega)=(1+\varepsilon)\,\kappa$, where $\kappa=T_p(B^n)^{(p-1)\sigma}\Lambda_{p,q}(B^n)$, and let $\eta=\delta_{\mathrm{BM}}(\Gamma_pL_u,B^n)$. Then there exists $A\in\mathrm{GL}(n)$ such that
\begin{equation}\label{eq:reduction}
T_p(A^{-1}\Omega)^{(p-1)\sigma}\,\Lambda_{p,q}(A^{-1}\Omega)\leq(1+\varepsilon)\,e^{(p\sigma+n\theta)\eta}\,\kappa,
\end{equation}
where $\theta$ is as in \eqref{eq:Wulff}, and $\eta\leq\frac{2n+p}{p}\,\delta_{\mathrm{BM}}(\Pi^*_pu,B^n)$. In particular, if $\varepsilon\leq1$, the left-hand side of \eqref{eq:reduction} is at most $\big(1+C\varepsilon^{1/(840(n+p))}\big)\kappa$, with $C=C(n,p,q)$. If $p=2$, then $\eta=0$ and $A\in\mathrm{SL}(n)$.
